package api

import (
	"embed"
	"net/http"
	"strings"
)

// The original's JSON schemas, byte for byte as its /v2/schemas/* returns
// them (captured from Glance 2026.2 in DevStack): they are static documents
// generated by its code, so serving the same bytes is the exact contract.
//
//go:embed schemas/*.json
var schemaFiles embed.FS

func (h *Handler) schema(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", "GET")
		h.status(w, 405, "Method not implemented.")
		return
	}
	name := r.PathValue("name")
	if group := r.PathValue("group"); group != "" {
		name = group + "-" + name
	}
	if strings.ContainsAny(name, "/.") {
		h.status(w, 404, "Schema not implemented.")
		return
	}
	data, err := schemaFiles.ReadFile("schemas/" + name + ".json")
	if err != nil {
		h.status(w, 404, "The resource could not be found.")
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(200)
	_, _ = w.Write(data)
}
